import { Command } from 'commander';
import ora from 'ora';
import { git } from '../utils/git.js';

function renderHeatmap(commits: number[]) {
  const shades = [' ', '.', ':', '*', 'o', 'O', '#', '@'];
  return commits
    .map(count => shades[Math.min(shades.length - 1, Math.floor(count / 2))])
    .join('');
}

export function registerFun(program: Command) {
  const fun = program.command('fun').description('Gamification and visuals');

  fun
    .command('streak')
    .description('Show daily commit streak')
    .action(async () => {
      const log = await git().raw(['log', '--since=30.days', '--pretty=%ad', '--date=short']);
      const days = log.split('\n').filter(Boolean);
      const counts: Record<string, number> = {};
      days.forEach(d => counts[d] = (counts[d] || 0) + 1);
      const streak = Object.keys(counts).length;
      console.log(`🔥 Streak: ${streak} days in last month`);
    });

  fun
    .command('art')
    .description('ASCII art of commit activity')
    .action(async () => {
      const log = await git().raw(['log', '--since=14.days', '--pretty=%ad', '--date=short']);
      const days = log.split('\n').filter(Boolean);
      const counts: Record<string, number> = {};
      days.forEach(d => counts[d] = (counts[d] || 0) + 1);
      const values = Object.values(counts);
      console.log(renderHeatmap(values));
    });

  fun
    .command('health')
    .description('Repository health score')
    .action(async () => {
      const spinner = ora('Computing health score...').start();
      const status = await git().status();
      const branchCount = (await git().branchLocal()).all.length;
      const dirtyPenalty = status.files.length > 5 ? 20 : status.files.length * 2;
      const score = Math.max(0, 100 - dirtyPenalty - Math.max(0, branchCount - 10));
      spinner.succeed(`Health score: ${score}`);
    });
}
